//! Direct public negacyclic functional on the compact signed source `sigma*M`.

use akita_error::AkitaError;
use jolt_field::{Ring, Unreduced};

use crate::protocol::{
    algebra::eq_table,
    ring::{functional_kernel_table_i16_with_round, PublicRingKeys},
    source_tables::SourceTables,
    stage::evaluate_compressed,
    FalconDegree, FalconWitness,
};
use crate::substrate::OpeningField as E;

type Product = <E as Unreduced>::Product;

/// Prover for the degree-three summand `w_ring * sigma * M`. The public
/// functional table and first message are generated by exact negacyclic
/// convolution. Later rounds transfer their lanes to the fused stage driver.
pub(super) struct Prover {
    weights: Vec<E>,
    /// One `eq(row_point, row)` factor per record. Keep this out of
    /// the coefficient table until each row's coefficient polynomial has
    /// been contracted.
    row_scale: Option<Vec<E>>,
    coefficient_rounds: usize,
    claim: E,
    pending: [E; 3],
}

impl Prover {
    pub(super) fn new(
        batch: &FalconWitness,
        tables: &SourceTables,
        magnitude: &[i16],
        degree: FalconDegree,
        projection_point: &[E],
        input_claim: E,
    ) -> Result<Self, AkitaError> {
        let coefficient_vars = degree.logn();
        let records = batch.padded_rows;
        let (coefficient_point, row_point) = projection_point.split_at(coefficient_vars);
        let cells = records * degree.degree();
        let sigma = tables.sigma_view();
        if batch.h.len() != cells || magnitude.len() != cells || sigma.len() != cells {
            return Err(AkitaError::InvalidInput(
                "ring-functional source shape mismatch".into(),
            ));
        }
        let row_scale = eq_table(row_point);
        let (weights, pending) = functional_kernel_table_i16_with_round(
            &batch.h,
            records,
            batch.live_rows,
            coefficient_point,
            sigma,
            magnitude,
            &row_scale,
        );
        Ok(Self {
            weights,
            row_scale: Some(row_scale),
            coefficient_rounds: coefficient_vars,
            claim: input_claim,
            pending,
        })
    }

    /// Move the prefix's live lanes into the integrated stage-three sweep.
    pub(super) fn into_fused(self, gamma: E) -> FusedState {
        FusedState {
            weights: self.weights,
            row_scale: self.row_scale,
            coefficient_rounds: self.coefficient_rounds,
            claim: gamma * self.claim,
            gamma,
        }
    }

    pub(super) fn initial_message(&self, gamma: E) -> [E; 3] {
        self.pending.map(|coefficient| gamma * coefficient)
    }
}

/// Ring state after the compact stage-three prefix. The fused engine owns
/// every lane traversal; this state advances only the scalar claim and phase.
pub(super) struct FusedState {
    pub(super) weights: Vec<E>,
    pub(super) row_scale: Option<Vec<E>>,
    pub(super) coefficient_rounds: usize,
    pub(super) claim: E,
    pub(super) gamma: E,
}

impl FusedState {
    pub(super) fn claim(&self) -> E {
        self.claim
    }

    /// Advance before evaluating the next round. On the coefficient-to-row
    /// transition, retain `row_scale` until the engine has multiplied each new
    /// folded weight by its row factor, then let the engine clear it.
    pub(super) fn bind_metadata(&mut self, message: [E; 3], challenge: E) {
        self.claim = evaluate_compressed(message, self.claim, challenge);
        self.coefficient_rounds = self.coefficient_rounds.saturating_sub(1);
    }
}

/// The transmitted cubic coefficients, with row factors deliberately absent.
/// Sum these unreduced products within each row before multiplying `row_scale`.
#[inline]
pub(super) fn pair_products(weights: [E; 2], sigma: [E; 2], magnitude: [E; 2]) -> [Product; 3] {
    let [w0, w1] = weights;
    let [s0, s1] = sigma;
    let [m0, m1] = magnitude;
    let dw = w1 - w0;
    let ds = s1 - s0;
    let dm = m1 - m0;
    let quadratic = ds * dm;
    let left = s0 * m0;
    let right = s1 * m1;
    [
        w0.mul_unreduced(left),
        dw.mul_unreduced(right - left - quadratic) + w0.mul_unreduced(quadratic),
        dw.mul_unreduced(quadratic),
    ]
}

pub(super) fn terminal<C>(
    gamma: E,
    h: PublicRingKeys<'_, C>,
    records: usize,
    projection_point: &[E],
    point: &[E],
    terminal_evaluations: &[E; 9],
) -> E
where
    C: Copy + Sync + Into<i64>,
{
    let ring_weight = h.functional_evaluation(records, projection_point, point);
    let magnitude = terminal_evaluations[2]
        + E::from_i64(8) * terminal_evaluations[3]
        + E::from_i64(128) * terminal_evaluations[4]
        + E::from_i64(1_092);
    gamma * ring_weight * terminal_evaluations[5] * magnitude
}

#[cfg(test)]
mod tests {
    use super::super::fused_rounds::tests::check_relations;
    use super::*;

    #[test]
    fn direct_cubic_rounds_match_compact_signed_sources_and_affine_terminal() {
        for degree in [FalconDegree::Falcon512, FalconDegree::Falcon1024] {
            for mode in 0..4 {
                check_relations(&[7], degree, 2, mode);
            }
        }
    }

    #[test]
    fn deferred_row_scaling_matches_direct_coefficient_and_row_rounds() {
        for degree in [FalconDegree::Falcon512, FalconDegree::Falcon1024] {
            for mode in 0..6 {
                check_relations(&[7], degree, 4, mode);
            }
        }
    }
}
